        if not isinstance(edge, (list, tuple)) or len(edge) != 2:
            continue
        u, v = edge
        if u not in node_set or v not in node_set:
            continue
        if v not in adj[u]:
            adj[u].add(v)
            indegree[v] += 1

    heap = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in sorted(adj[u]):
            indegree[v] -= 1
